# app.py
"""
Arc-2-Neo-Drives: Minimalist 2-Input Desired-State Reconciler.
Engineered exclusively for Option A: Testament <number> -> Entities.
Zero-friction: No authorization gates, no mode selectors. Pure utility.
"""

import streamlit as st
import core.drive_ops as drive_ops
import core.reconciler as reconciler

# --- PAGE SETUP ---
st.set_page_config(
    page_title="Folder Template Reconciler",
    page_icon="⚡",
    layout="wide",
    initial_sidebar_state="collapsed",
)

# --- MINIMALIST DARK STYLING ---
st.markdown("""
<style>
    /* Remove default top margins & padding */
    .block-container {
        padding-top: 2rem;
        padding-bottom: 2rem;
        max-width: 1100px;
    }
    /* Input field styling */
    div[data-testid="stTextInput"] > div > div > input {
        border-radius: 8px;
        background: #13171f;
        border: 1px solid #2d3748;
        color: #f7fafc;
        font-size: 0.95rem;
    }
    /* Button refinement */
    button[kind="primary"] {
        border-radius: 8px;
        font-weight: 600;
        background: #3182ce;
        border: none;
    }
    button[kind="secondary"] {
        border-radius: 8px;
        font-weight: 600;
        background: #2b6cb0;
        color: white;
        border: none;
    }
    /* KPI card styling */
    .stat-pill {
        display: inline-block;
        padding: 4px 12px;
        border-radius: 16px;
        font-size: 0.85rem;
        font-weight: 600;
        margin-right: 8px;
        margin-bottom: 8px;
    }
    .pill-green { background: rgba(72, 187, 120, 0.2); color: #48bb78; border: 1px solid #48bb78; }
    .pill-yellow { background: rgba(236, 201, 75, 0.2); color: #ecc94b; border: 1px solid #ecc94b; }
    .pill-gray { background: rgba(160, 174, 192, 0.2); color: #a0aec0; border: 1px solid #a0aec0; }
    .pill-red { background: rgba(245, 101, 101, 0.25); color: #f56565; border: 1px solid #f56565; }
    .pill-blue { background: rgba(66, 153, 225, 0.2); color: #4299e1; border: 1px solid #4299e1; }
</style>
""", unsafe_allow_html=True)

# --- MINIMALIST HEADER ---
st.title("⚡ Folder Template Reconciler")
st.caption("Option A: Enforce entity archetype template across all Testament groups.")

st.markdown("---")

# =====================================================================
# THE 2 INPUTS (NO CLUTTER)
# =====================================================================
col1, col2 = st.columns(2)

with col1:
    template_url = st.text_input(
        "📐 Template Folder (Archetype):",
        value=st.session_state.get(
            "cached_template",
            "https://drive.google.com/drive/folders/1qPYOlZ3-LlnfiBRorXUnNa_0yVZcILvM?usp=drive_link"
        ),
        placeholder="Link thư mục mẫu (ví dụ: Entropy 0)",
    )

with col2:
    data_root_url = st.text_input(
        "🗂️ Data Root Folder (Collection):",
        value=st.session_state.get(
            "cached_data_root",
            "https://drive.google.com/drive/folders/14J8QBCqdSQOPerLBIaR2jLyYhZ4WbJUA?usp=drive_link"
        ),
        placeholder="Link thư mục gốc (ví dụ: Testaments)",
    )

# Action buttons
c_btn1, c_btn2, _ = st.columns([1, 1, 3])
with c_btn1:
    btn_scan = st.button("🔍 Quét Đối Chiếu (Scan)", type="primary", use_container_width=True)
with c_btn2:
    btn_apply = st.button("🚀 Thực Thi Đồng Bộ (Apply)", type="secondary", use_container_width=True)

st.markdown("---")

# =====================================================================
# SCAN & RECONCILIATION LOGIC
# =====================================================================
if btn_scan or ("reconcile_plan" not in st.session_state and not btn_apply):
    # Auto-run initial scan on load or button click
    t_id = drive_ops.extract_folder_id_from_url(template_url)
    d_id = drive_ops.extract_folder_id_from_url(data_root_url)

    if t_id and d_id:
        st.session_state.cached_template = template_url
        st.session_state.cached_data_root = data_root_url

        with st.spinner("Đang kiểm tra và đối chiếu dữ liệu..."):
            try:
                schema = reconciler.extract_schema_from_drive_folder(t_id)
                plan = reconciler.plan_entity_level_reconciliation(
                    data_root_id=d_id,
                    template_schema=schema,
                    template_name=schema.get("name", "Archetype"),
                )
                st.session_state.reconcile_plan = plan
            except Exception as e:
                st.error(f"❌ Lỗi: {e}")

# =====================================================================
# RESULTS & METRICS DISPLAY
# =====================================================================
if "reconcile_plan" in st.session_state:
    plan = st.session_state.reconcile_plan
    summary = plan.summary()

    # Clean status pills summary
    st.markdown(f"""
    <div>
        <span class="stat-pill pill-blue">📁 {summary['total_groups']} Groups</span>
        <span class="stat-pill pill-blue">📦 {summary['total_entities']} Entities</span>
        <span class="stat-pill pill-green">🟢 +{summary['create_count']} Cần tạo mới</span>
        <span class="stat-pill pill-yellow">🟡 ~{summary['update_desc_count']} Cần sửa desc</span>
        <span class="stat-pill pill-gray">⚪ -{summary['prune_empty_count']} Thừa rỗng (xóa)</span>
        <span class="stat-pill {'pill-red' if summary['flagged_red_count'] > 0 else 'pill-gray'}">🔴 !{summary['flagged_red_count']} Báo đỏ có file</span>
        <span class="stat-pill pill-green">✅ ={summary['compliant_count']} Chuẩn khớp</span>
    </div>
    """, unsafe_allow_html=True)

    # Red Alert Banner if populated rogue folders exist
    if plan.extraneous_populated:
        st.error(f"🚨 Phát hiện {len(plan.extraneous_populated)} thư mục thừa đang chứa dữ liệu! (Hệ thống giữ nguyên bảo vệ 100%):")
        for it in plan.extraneous_populated:
            st.markdown(f"- 🔴 **`{it.relative_path}`** ({it.files_count} files, {it.subfolders_count} subfolders)")

    # Group & Entity Overview
    st.markdown("##### 📂 Cấu trúc các nhóm & Entity:")
    for g in plan.groups:
        with st.expander(f"📁 **{g.group_name}** ({len(g.entity_plans)} entities)", expanded=True):
            if g.empty_note:
                st.caption(f"ℹ️ {g.empty_note}")
            else:
                for ep in g.entity_plans:
                    st.markdown(f"**📦 Entity `{ep.target_root_name}`:**")
                    for it in ep.items:
                        if it.action_type == "MATCH":
                            st.markdown(f"&nbsp;&nbsp;&nbsp;&nbsp;✅ `{it.relative_path}` (Khớp template)")
                        elif it.action_type == "CREATE":
                            st.markdown(f"&nbsp;&nbsp;&nbsp;&nbsp;🟢 **TẠO MỚI**: `{it.relative_path}`")
                        elif it.action_type == "UPDATE_DESC":
                            st.markdown(f"&nbsp;&nbsp;&nbsp;&nbsp;🟡 **SỬA DESC**: `{it.relative_path}` $\\rightarrow$ `{it.expected_desc}`")
                        elif it.action_type == "PRUNE_EMPTY":
                            st.markdown(f"&nbsp;&nbsp;&nbsp;&nbsp;⚪ **XÓA THỪA RỖNG**: `{it.relative_path}`")
                        elif it.action_type == "FLAG_RED":
                            st.markdown(f"&nbsp;&nbsp;&nbsp;&nbsp;🔴 **CẢNH BÁO CÓ FILE**: `{it.relative_path}`")

    # Apply Execution
    if btn_apply:
        st.markdown("---")
        log_box = st.empty()
        def log_cb(msg: str):
            log_box.code(msg)

        with st.spinner("Đang thực thi đồng bộ chuẩn hóa lên Google Drive..."):
            try:
                res = reconciler.execute_multi_entity_reconciliation(plan, dry_run=False, log_callback=log_cb)
                st.success(
                    f"🎉 Hoàn tất đồng bộ!\n"
                    f"- Tạo mới: {res['created_count']} | Sửa desc: {res['updated_desc_count']} | "
                    f"Xóa rác: {res['pruned_empty_count']} | Báo đỏ bảo vệ: {res['flagged_red_count']}"
                )
                del st.session_state["reconcile_plan"]
                st.rerun()
            except Exception as ex:
                st.error(f"❌ Lỗi: {ex}")

