1	import React, { useState } from 'react';
2	import { EntityPlan, ActionItem } from '../types';
3	import {
4	  Folder,
5	  ExternalLink,
6	  Zap,
7	  CheckCircle2,
8	  ChevronDown,
9	  FileEdit,
10	  FolderPlus,
11	  RefreshCw,
12	  Trash2,
13	  ArrowRight,
14	  X,
15	  File,
16	  Edit2,
17	  Check,
18	} from 'lucide-react';
19	
20	interface EntityFolderCardProps {
21	  entityPlan: EntityPlan;
22	  onFixEntity: (entityPlan: EntityPlan) => void;
23	  isExecuting: boolean;
24	  isFullWidth?: boolean;
25	  viewMode?: 'all' | 'conflict' | 'perfected';
26	  onRenameEntity?: (entityId: string, newName: string) => Promise<void>;
27	  onTrashFolder?: (folderId: string) => Promise<void>;
28	}
29	
30	interface TreeNode {
31	  item: ActionItem;
32	  path: string;
33	  name: string;
34	  children: TreeNode[];
35	}
36	
37	function buildEntityTree(items: ActionItem[], viewMode: 'all' | 'conflict' | 'perfected' = 'all'): TreeNode[] {
38	  let subItems = items.filter((i) => {
39	    const parts = i.relative_path.split('/').filter(Boolean);
40	    return parts.length > 2;
41	  });
42	
43	  if (viewMode === 'conflict') {
44	    const conflictPaths = new Set(
45	      subItems.filter((i) => i.action_type !== 'MATCH').map((i) => i.relative_path)
46	    );
47	    // Show only conflict folders or folders containing conflict descendants
48	    subItems = subItems.filter((i) => {
49	      if (i.action_type !== 'MATCH') return true;
50	      return Array.from(conflictPaths).some((cp) => cp.startsWith(i.relative_path + '/'));
51	    });
52	  } else if (viewMode === 'perfected') {
53	    // Show only non-conflict / healthy subfolders
54	    subItems = subItems.filter((i) => i.action_type === 'MATCH');
55	  }
56	
57	  const nodeMap = new Map<string, TreeNode>();
58	  const rootNodes: TreeNode[] = [];
59	
60	  const sorted = [...subItems].sort(
61	    (a, b) => a.relative_path.split('/').length - b.relative_path.split('/').length
62	  );
63	
64	  for (const item of sorted) {
65	    const parts = item.relative_path.split('/').filter(Boolean);
66	    const node: TreeNode = {
67	      item,
68	      path: item.relative_path,
69	      name: item.folder_name,
70	      children: [],
71	    };
72	    nodeMap.set(item.relative_path, node);
73	
74	    const parentPath = parts.slice(0, -1).join('/');
75	    const parentNode = nodeMap.get(parentPath);
76	
77	    if (parentNode) {
78	      parentNode.children.push(node);
79	    } else {
80	      rootNodes.push(node);
81	    }
82	  }
83	
84	  return rootNodes;
85	}
86	
87	export const EntityFolderCard: React.FC<EntityFolderCardProps> = ({
88	  entityPlan,
89	  onFixEntity,
90	  isExecuting,
91	  isFullWidth = false,
92	  viewMode = 'all',
93	  onRenameEntity,
94	  onTrashFolder,
95	}) => {
96	  // Tracks selected folder path at each tree level
97	  const [selectedPathsByLevel, setSelectedPathsByLevel] = useState<Record<number, string | null>>({});
98	
99	  // Inline rename state
100	  const [isEditingName, setIsEditingName] = useState(false);
101	  const [editName, setEditName] = useState(entityPlan.target_root_name);
102	  const [isSavingName, setIsSavingName] = useState(false);
103	
104	  const handleSaveName = async (e: React.FormEvent) => {
105	    e.preventDefault();
106	    const clean = editName.trim();
107	    if (!clean || clean === entityPlan.target_root_name) {
108	      setIsEditingName(false);
109	      return;
110	    }
111	    setIsSavingName(true);
112	    try {
113	      await onRenameEntity?.(entityPlan.target_root_id, clean);
114	      setIsEditingName(false);
115	    } finally {
116	      setIsSavingName(false);
117	    }
118	  };
119	
120	  const tree = buildEntityTree(entityPlan.items, viewMode);
121	  const mismatches = entityPlan.items.filter((i) => i.action_type !== 'MATCH');
122	  const hasMismatches = mismatches.length > 0;
123	
124	  const handleFolderClick = (level: number, node: TreeNode) => {
125	    setSelectedPathsByLevel((prev) => {
126	      // If clicking already selected folder, collapse it
127	      if (prev[level] === node.path) {
128	        const next = { ...prev };
129	        delete next[level];
130	        // clean up deeper levels too
131	        Object.keys(next).forEach((k) => {
132	          if (Number(k) >= level) delete next[Number(k)];
133	        });
134	        return next;
135	      }
136	
137	      // Otherwise select it and clear deeper levels
138	      const next = { ...prev, [level]: node.path };
139	      Object.keys(next).forEach((k) => {
140	        if (Number(k) > level) delete next[Number(k)];
141	      });
142	      return next;
143	    });
144	  };
145	
146	  const getStatusBadge = (item: ActionItem) => {
147	    switch (item.action_type) {
148	      case 'RENAME':
149	        return (
150	          <span className="badge badge-rename" style={{ fontSize: '10px', padding: '1px 6px' }}>
151	            <FileEdit size={10} style={{ marginRight: '2px' }} /> Rename
152	          </span>
153	        );
154	      case 'CREATE':
155	        return (
156	          <span className="badge badge-create" style={{ fontSize: '10px', padding: '1px 6px' }}>
157	            <FolderPlus size={10} style={{ marginRight: '2px' }} /> Missing
158	          </span>
159	        );
160	      case 'UPDATE_DESC':
161	        return (
162	          <span className="badge badge-update" style={{ fontSize: '10px', padding: '1px 6px' }}>
163	            <RefreshCw size={10} style={{ marginRight: '2px' }} /> Metadata
164	          </span>
165	        );
166	      case 'PRUNE_EMPTY':
167	        return (
168	          <span className="badge badge-prune" style={{ fontSize: '10px', padding: '1px 6px' }}>
169	            <Trash2 size={10} style={{ marginRight: '2px' }} /> Unwanted
170	          </span>
171	        );
172	      case 'CUSTOM':
173	        return (
174	          <span className="badge" style={{ fontSize: '10px', padding: '1px 6px', background: 'var(--bg-canvas)', border: '1px solid var(--border-light)', color: 'var(--text-dim)' }}>
175	            Custom
176	          </span>
177	        );
178	      case 'MATCH':
179	      default:
180	        return (
181	          <span style={{ fontSize: '10.5px', color: 'var(--success)', display: 'inline-flex', alignItems: 'center', gap: '0.2rem' }}>
182	            <CheckCircle2 size={11} /> In sync
183	          </span>
184	        );
185	    }
186	  };
187	
188	  // Renders a grid of Google Drive folder cards for a specific list of nodes
189	  const renderFolderGrid = (nodes: TreeNode[], level = 0) => {
190	    const activePath = selectedPathsByLevel[level];
191	    const activeNode = nodes.find((n) => n.path === activePath);
192	
193	    return (
