const handleFixAll = async () => {
  await onExecutePlan(plan);
};

// Sovereign Mirroring to Google Drive Slave
const [isMirroring, setIsMirroring] = useState(false);

const handleMirrorToDrive = async () => {
  setIsMirroring(true);
  try {
    const res = await fetch('/api/drive/sync_push', { method: 'POST' });
    const data = await res.json();
    if (!res.ok) throw new Error(data.detail || 'Failed to mirror to Google Drive');
    addToast(
      'success',
      'Google Drive Mirrored',
      `Pushed to Drive: ${data.created_on_drive} created, ${data.renamed_on_drive} renamed (${data.duration_ms} ms)`
    );
    onRefresh();
  } catch (err: any) {
    addToast('error', 'Mirroring Failed', err.message);
  } finally {
    setIsMirroring(false);
  }
};

