121	  const [drawerOpen, setDrawerOpen] = useState<boolean>(false);
122	  const [selectedRecord, setSelectedRecord] = useState<TableRecord | null>(null);
123	  const [authModalOpen, setAuthModalOpen] = useState<boolean>(false);
124	  const [tableSettingsOpen, setTableSettingsOpen] = useState<boolean>(false);
125	  const [newTableModalOpen, setNewTableModalOpen] = useState<boolean>(false);
126	  const [defaultNewTableGroupId, setDefaultNewTableGroupId] = useState<string | null>(null);
127	  const [outlinerOpen, setOutlinerOpen] = useState<boolean>(true);
128	
129	  // Responsive Hook
130	  const [isMobile, setIsMobile] = useState<boolean>(window.innerWidth < 768);
131	
132	  useEffect(() => {
133	    const handleResize = () => setIsMobile(window.innerWidth < 768);
134	    window.addEventListener('resize', handleResize);
135	    return () => window.removeEventListener('resize', handleResize);
136	  }, []);
137	
138	  const toggleTheme = () => {
139	    const next = theme === 'dark' ? 'light' : 'dark';
140	    setTheme(next);
141	    document.documentElement.setAttribute('data-theme', next);
142	  };
143	
144	  // Pure RAM lazy-loader for foreign relation options (0ms initial startup, zero waterfall)
145	  const syncTableToRelationStore = (tableName: string, tableRecordsList: TableRecord[]) => {
146	    const byId: Record<string, TableRecord> = {};
147	    tableRecordsList.forEach((r: TableRecord) => {
148	      if (r && r.id) byId[r.id] = r;
149	    });
150	    setRelationStore((prev) => ({ ...prev, [tableName]: byId }));
151	
152	    const opts = tableRecordsList.slice(0, 150).map((r: TableRecord) => {
153	      const label = r.name || r.main_content || r.title || r.headline || r.id;
154	      return { id: r.id, label: String(label).slice(0, 50) };
155	    });
156	    setRelationOptions((prev) => ({ ...prev, [tableName]: opts }));
157	  };
158	
159	  const inFlightRelationsRef = useRef<Set<string>>(new Set());
160	  const tableRecordsRef = useRef(tableRecords);
161	  tableRecordsRef.current = tableRecords;
162	
163	  const ensureRelationLoaded = useCallback(async (targetTable?: string) => {
164	    if (!targetTable) return;
165	    const currentRecs = tableRecordsRef.current[targetTable];
166	    if (currentRecs && currentRecs.length > 0) return;
167	    if (inFlightRelationsRef.current.has(targetTable)) return;
168	
169	    inFlightRelationsRef.current.add(targetTable);
170	    try {
171	      const res = await api.getRecords(targetTable);
172	      if (res.records) {
173	        setTableRecords((prev) => ({ ...prev, [targetTable]: res.records }));
174	        syncTableToRelationStore(targetTable, res.records);
175	      }
176	    } catch {
177	      // Soft-fail for missing table
178	    } finally {
179	      inFlightRelationsRef.current.delete(targetTable);
180	    }
181	  }, []);
182	
183	  // Preload foreign relation records for current table's relation columns
184	  useEffect(() => {
